import{_ as a,o as r,c as t,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Natural graha nature and house-set witnesses","description":"A source-bounded, versioned decision table classifies each canonical graha as a natural benefic, natural malefic, or unknown and derives decisive three-valued house-set witness predicates.","frontmatter":{"title":"Natural graha nature and house-set witnesses","description":"A source-bounded, versioned decision table classifies each canonical graha as a natural benefic, natural malefic, or unknown and derives decisive three-valued house-set witness predicates.","editLink":false},"headers":[],"relativePath":"computations/personal.natural-graha-nature.md","filePath":"_generated/computations/personal.natural-graha-nature.md","lastUpdated":null}'),o={name:"computations/personal.natural-graha-nature.md"};function s(i,e,l,c,d,u){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="natural-graha-nature-and-house-set-witnesses" tabindex="-1">Natural graha nature and house-set witnesses <a class="header-anchor" href="#natural-graha-nature-and-house-set-witnesses" aria-label="Permalink to &quot;Natural graha nature and house-set witnesses&quot;">​</a></h1><p><code class="computation-route-id">personal.natural-graha-nature</code></p><p>A source-bounded, versioned decision table classifies each canonical graha as a natural benefic, natural malefic, or unknown and derives decisive three-valued house-set witness predicates.</p><h2 id="assurance" tabindex="-1">Assurance <a class="header-anchor" href="#assurance" aria-label="Permalink to &quot;Assurance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Current statement</th></tr></thead><tbody><tr><td>Documented and traceable</td><td>Yes — the canonical record includes the process and a worked example.</td></tr><tr><td>Regression or reproduction checked</td><td>Linked to 2 repository test file(s).</td></tr><tr><td>Independently source-supported</td><td>Available only for the explicitly named provenance claims or comparison cells.</td></tr></tbody></table><h2 id="computation-method" tabindex="-1">Computation method <a class="header-anchor" href="#computation-method" aria-label="Permalink to &quot;Computation method&quot;">​</a></h2><p><strong>Method type:</strong> <code>decision-table</code></p><p>Validate a complete canonical chart, classify fixed grahas, resolve Chandra from quantized Surya-Chandra elongation, resolve Budha from same-Rasi companions, then use decisive known witnesses before unknown occupants for house-set predicates.</p><h3 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to &quot;Process&quot;">​</a></h3><ol><li>Require exactly one valid canonical record for Surya, Chandra, Kuja, Budha, Guru, Shukra, Shani, Rahu and Ketu; otherwise return unknown for all natures.</li><li>Reconstruct absolute longitude from Rasi index and in-Rasi degree, normalize Chandra minus Surya to 0-360 degrees, and quantize to ten decimal places using non-negative round-half-up integer units.</li><li>Mark Chandra unknown inside the inclusive 0.02-degree guards around 0, 180 and 360 degrees, benefic between the new and full-Moon guards, and malefic between the full- and new-Moon guards.</li><li>Assign Surya, Kuja, Shani, Rahu and Ketu as fixed malefics and Guru and Shukra as fixed benefics.</li><li>Make Budha malefic when any resolved malefic shares its sidereal Rasi; if only phase-unknown Chandra could decide, return unknown; otherwise make Budha benefic.</li><li>For an existential benefic rule, pass on any known benefic, otherwise return unknown for an unknown-nature occupant, otherwise fail.</li><li>For a forbidden malefic rule, fail on any known malefic, otherwise return unknown for an unknown-nature occupant, otherwise pass.</li></ol><h3 id="formulae" tabindex="-1">Formulae <a class="header-anchor" href="#formulae" aria-label="Permalink to &quot;Formulae&quot;">​</a></h3><h4 id="quantized-chandra-elongation" tabindex="-1">Quantized Chandra elongation <a class="header-anchor" href="#quantized-chandra-elongation" aria-label="Permalink to &quot;Quantized Chandra elongation&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q = floor((((L(Chandra) - L(Surya)) mod 360) * 10^10) + 0.5)</span></span></code></pre></div><ul><li>L(graha): sidereal absolute longitude reconstructed from Rasi and degree</li><li>Q: non-negative integer quantum at ten decimal places</li><li>floor(x + 0.5): shared non-negative round-half-up tie rule</li></ul><h4 id="chandra-nature" tabindex="-1">Chandra nature <a class="header-anchor" href="#chandra-nature" aria-label="Permalink to &quot;Chandra nature&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unknown when min(Q, |Q-180*10^10|, |360*10^10-Q|) &lt;= 0.02*10^10; benefic when Q &lt; 180*10^10 outside the guard; otherwise malefic</span></span></code></pre></div><ul><li>0.02 degrees: disclosed inclusive project precision guard</li><li>0, 180 and 360 degrees: new-Moon and full-Moon phase boundaries</li></ul><h4 id="decisive-witness-aggregation" tabindex="-1">Decisive witness aggregation <a class="header-anchor" href="#decisive-witness-aggregation" aria-label="Permalink to &quot;Decisive witness aggregation&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>existential benefic: known benefic &gt; unknown &gt; fail; forbidden malefic: known malefic &gt; unknown &gt; pass</span></span></code></pre></div><ul><li>known witness: an occupant whose natural nature resolves benefic or malefic</li><li>unknown: an occupant whose unresolved nature could change the predicate</li></ul><h3 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h3><h4 id="half-quantum-full-moon-boundary" tabindex="-1">Half-quantum full-Moon boundary <a class="header-anchor" href="#half-quantum-full-moon-boundary" aria-label="Permalink to &quot;Half-quantum full-Moon boundary&quot;">​</a></h4><p><strong>Inputs</strong></p><ul><li>Surya: Mesha 10.0 degrees</li><li>Chandra: Tula 9.97999999995 degrees</li><li>Guard: 0.02 degrees</li></ul><p><strong>Calculation</strong></p><ol><li>Raw elongation is 179.97999999995 degrees.</li><li>Non-negative half-up quantization produces Q = 179.98 * 10^10.</li><li>The distance to 180 degrees equals the inclusive guard.</li></ol><p><strong>Result</strong></p><ul><li>Chandra nature: unknown</li><li>Python and TypeScript return the same boundary result</li></ul><h4 id="decisive-benefic-beside-an-unresolved-occupant" tabindex="-1">Decisive benefic beside an unresolved occupant <a class="header-anchor" href="#decisive-benefic-beside-an-unresolved-occupant" aria-label="Permalink to &quot;Decisive benefic beside an unresolved occupant&quot;">​</a></h4><p><strong>Inputs</strong></p><ul><li>Target house 7 contains Guru and phase-unknown Chandra</li><li>Predicate: existential natural benefic</li></ul><p><strong>Calculation</strong></p><ol><li>Guru is a resolved natural benefic.</li><li>Chandra remains unknown, but cannot undo the known existential witness.</li></ol><p><strong>Result</strong></p><ul><li>Predicate: pass</li><li>Evidence names Guru as the decisive witness</li></ul><h3 id="method-notes" tabindex="-1">Method notes <a class="header-anchor" href="#method-notes" aria-label="Permalink to &quot;Method notes&quot;">​</a></h3><ul><li>The two textual authorities agree on the operative natural-nature categories but do not supply the numerical guard or a conjunction orb.</li><li>Whole-window certification additionally requires phase-boundary and every relevant Rasi-ingress transition from issue #254.</li></ul><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p><strong>Owning layer:</strong> <code>personal</code><br><strong>Claim kind:</strong> <code>textual-rule</code><br><strong>Time basis:</strong> One instantaneous Drik/Lahiri, mean-node, Whole Sign election-chart snapshot. This primitive does not sample a time window or call an ephemeris.</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><ul><li>complete canonical Surya-through-Ketu sidereal Rasi, degree, Whole Sign house and retrograde facts</li><li>non-empty required or forbidden house set with integer houses 1-12</li></ul><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><ul><li>complete flag and benefic, malefic or unknown nature for all nine grahas</li><li>existential natural-benefic house witness as pass, fail or unknown</li><li>forbidden natural-malefic house witness as pass, fail or unknown</li><li>human-readable decisive or unresolved evidence</li></ul><h2 id="references-and-evidence" tabindex="-1">References and evidence <a class="header-anchor" href="#references-and-evidence" aria-label="Permalink to &quot;References and evidence&quot;">​</a></h2><p><strong>Evidence classes:</strong> <code>textual</code>, <code>project_heuristic</code><br><strong>Verification states:</strong> <code>verified</code>, <code>heuristic</code><br></p><p>Phaladeepika II.27 and BPHS 3.11 support the natural-nature categories. The numerical lunar guard, ten-decimal half-up quantization, same-Rasi Budha association and decisive unknown precedence are disclosed reproducibility conventions.</p><h3 id="election-chart-natural-graha-nature-phaladeepika-2-27" tabindex="-1"><code>election_chart.natural_graha_nature.phaladeepika_2_27</code> <a class="header-anchor" href="#election-chart-natural-graha-nature-phaladeepika-2-27" aria-label="Permalink to &quot;`election_chart.natural_graha_nature.phaladeepika_2_27`&quot;">​</a></h3><p><strong>Evidence class:</strong> <code>textual</code><br><strong>Verification state:</strong> <code>verified</code><br><strong>Locator:</strong> Chapter II, sloka 27, book pp. 19-20 (scan pp. 56-57)<br><strong>Last reviewed:</strong> 2026-09-09<br><strong>Scope:</strong> Enumerates waning Chandra, Surya, Kuja, Shani, Rahu and Ketu as malefic; Guru and Shukra as benefic; waxing Chandra as benefic; and Budha as malefic when joined to a malefic. It does not define a conjunction orb, a numerical phase boundary guard or functional lordship.</p><h4 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h4><ul><li><a href="https://archive.org/details/Phaladeepika2ndEd.1950ByVSubrahmanyaSastri" target="_blank" rel="noreferrer"><strong>Phaladeepika</strong></a> — Mantreswara; V. Subrahmanya Sastri English translation, second edition, 1950; authority type: <code>primary_text_translation</code></li></ul><h3 id="election-chart-natural-malefics-bphs-3-11-modern-witness" tabindex="-1"><code>election_chart.natural_malefics.bphs_3_11_modern_witness</code> <a class="header-anchor" href="#election-chart-natural-malefics-bphs-3-11-modern-witness" aria-label="Permalink to &quot;`election_chart.natural_malefics.bphs_3_11_modern_witness`&quot;">​</a></h3><p><strong>Evidence class:</strong> <code>textual</code><br><strong>Verification state:</strong> <code>verified</code><br><strong>Locator:</strong> Chapter 3, verse 11, Sanskrit compound analysis and English rendering<br><strong>Last reviewed:</strong> 2026-09-04<br><strong>Scope:</strong> A modern web witness for the natural-malefic enumeration: Surya, Kuja, Shani, Rahu, Ketu and waning Chandra, with Budha conditional on association with a malefic. It is not presented as a critical edition or as independent authority for the project&#39;s same-sign association inference.</p><h4 id="sources-1" tabindex="-1">Sources <a class="header-anchor" href="#sources-1" aria-label="Permalink to &quot;Sources&quot;">​</a></h4><ul><li><a href="https://enjoylearningsanskrit.com/scriptures/parashara/chapter-3/verse-11/" target="_blank" rel="noreferrer"><strong>Brihat Parashara Hora Shastra, chapter 3 verse 11</strong></a> — Attributed to Parashara; Enjoy Learning Sanskrit modern web transcription, word analysis, and English rendering; accessed 2026-09-04; not a critical edition; authority type: <code>modern_text_witness</code></li></ul><h3 id="election-chart-budha-same-sign-association-policy-v1" tabindex="-1"><code>election_chart.budha_same_sign_association_policy_v1</code> <a class="header-anchor" href="#election-chart-budha-same-sign-association-policy-v1" aria-label="Permalink to &quot;`election_chart.budha_same_sign_association_policy_v1`&quot;">​</a></h3><p><strong>Evidence class:</strong> <code>project_heuristic</code><br><strong>Verification state:</strong> <code>heuristic</code><br><strong>Locator:</strong> annaprasana-natural-malefic-lagna-v1; BPHS modern witness chapter 3 verse 11<br><strong>Last reviewed:</strong> 2026-09-04<br><strong>Scope:</strong> Interprets Budha&#39;s association condition only as same-sign physical occupation. No additional Budha failure is produced because any accompanying fixed natural malefic in Lagna already controls the prohibition. Aspect, dispositor and lordship associations are not inferred.</p><h4 id="sources-2" tabindex="-1">Sources <a class="header-anchor" href="#sources-2" aria-label="Permalink to &quot;Sources&quot;">​</a></h4><ul><li><a href="https://enjoylearningsanskrit.com/scriptures/parashara/chapter-3/verse-11/" target="_blank" rel="noreferrer"><strong>Brihat Parashara Hora Shastra, chapter 3 verse 11</strong></a> — Attributed to Parashara; Enjoy Learning Sanskrit modern web transcription, word analysis, and English rendering; accessed 2026-09-04; not a critical edition; authority type: <code>modern_text_witness</code></li></ul><h3 id="election-chart-raman-180-degree-paksha-policy-v1" tabindex="-1"><code>election_chart.raman_180_degree_paksha_policy_v1</code> <a class="header-anchor" href="#election-chart-raman-180-degree-paksha-policy-v1" aria-label="Permalink to &quot;`election_chart.raman_180_degree_paksha_policy_v1`&quot;">​</a></h3><p><strong>Evidence class:</strong> <code>project_heuristic</code><br><strong>Verification state:</strong> <code>heuristic</code><br><strong>Locator:</strong> B. V. Raman, Chapter II, inspected in the 2020 Chistabo derivative at internal printed p. 4 (physical PDF p. 7); annaprasana-natural-malefic-lagna-v1<br><strong>Last reviewed:</strong> 2026-09-04<br><strong>Scope:</strong> Implements the transcription&#39;s below-or-above-180-degree description as E = (Chandra longitude - Surya longitude) mod 360: 0 &lt; E &lt; 180 is waxing and 180 &lt; E &lt; 360 is waning. This ecliptic-longitude arithmetic is the named Raman policy rather than a blended lunar-phase tradition.</p><h4 id="sources-3" tabindex="-1">Sources <a class="header-anchor" href="#sources-3" aria-label="Permalink to &quot;Sources&quot;">​</a></h4><ul><li><a href="https://books.google.com/books/about/Muhurtha_Electional_Astrology.html?id=nHQlAcBkDXIC" target="_blank" rel="noreferrer"><strong>Muhurtha (Electional Astrology)</strong></a> — B. V. Raman; UBS Publishers&#39; Distributors, 1993, ISBN 9788185674681, 181 catalogued pages; authority type: <code>modern_synthesis</code></li><li><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer"><strong>Muhurtha (Electional Astrology) — Chistabo re-edited derivative</strong></a> — B. V. Raman; re-edited by Simon (Chistabo); 2020 re-edited transcription, 78 physical PDF pages; authority type: <code>inspected_derivative</code></li></ul><h3 id="election-chart-lunar-phase-boundary-guard-policy-v1" tabindex="-1"><code>election_chart.lunar_phase_boundary_guard_policy_v1</code> <a class="header-anchor" href="#election-chart-lunar-phase-boundary-guard-policy-v1" aria-label="Permalink to &quot;`election_chart.lunar_phase_boundary_guard_policy_v1`&quot;">​</a></h3><p><strong>Evidence class:</strong> <code>project_heuristic</code><br><strong>Verification state:</strong> <code>heuristic</code><br><strong>Locator:</strong> annaprasana-natural-malefic-lagna-v1; lunar_phase_guard_degrees=0.02<br><strong>Last reviewed:</strong> 2026-09-04<br><strong>Scope:</strong> Returns unknown at and within 0.02 degrees of either 0 or 180 degrees of solar elongation. The guard covers rounded sidecar degrees and the source&#39;s unclassified exact boundaries; it is a product precision policy, not a textual threshold.</p><h4 id="sources-4" tabindex="-1">Sources <a class="header-anchor" href="#sources-4" aria-label="Permalink to &quot;Sources&quot;">​</a></h4><ul><li>No external source is registered for this claim.</li></ul><h3 id="election-chart-mean-node-policy-v1" tabindex="-1"><code>election_chart.mean_node_policy_v1</code> <a class="header-anchor" href="#election-chart-mean-node-policy-v1" aria-label="Permalink to &quot;`election_chart.mean_node_policy_v1`&quot;">​</a></h3><p><strong>Evidence class:</strong> <code>project_heuristic</code><br><strong>Verification state:</strong> <code>heuristic</code><br><strong>Locator:</strong> DashaFlow election-chart response contract field engine.nodeConvention; annaprasana-natural-malefic-lagna-v1<br><strong>Last reviewed:</strong> 2026-09-04<br><strong>Scope:</strong> Fixes Rahu and Ketu to the sidecar&#39;s disclosed mean-node positions for this policy. The choice of mean rather than true nodes is an engineering convention, not wording supplied by the Annaprasana passage.</p><h4 id="sources-5" tabindex="-1">Sources <a class="header-anchor" href="#sources-5" aria-label="Permalink to &quot;Sources&quot;">​</a></h4><ul><li><a href="https://www.astro.com/swisseph/swephprg.htm" target="_blank" rel="noreferrer"><strong>Swiss Ephemeris</strong></a> — Astrodienst; Swiss Ephemeris 2.10 Programmer&#39;s Documentation and pyswisseph runtime used by the repository; authority type: <code>astronomical_reference</code></li></ul><p>The complete machine-readable source registry is available in <a href="/docs/reference/provenance.json"><code>provenance.json</code></a>. A regression fixture or same-code reproduction is not independent verification.</p><h2 id="reproduce-and-review" tabindex="-1">Reproduce and review <a class="header-anchor" href="#reproduce-and-review" aria-label="Permalink to &quot;Reproduce and review&quot;">​</a></h2><ul><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/tests/test_natural_graha_nature.py" target="_blank" rel="noreferrer"><code>tests/test_natural_graha_nature.py</code></a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/src/scorer/__tests__/natural-graha-nature.test.ts" target="_blank" rel="noreferrer"><code>src/scorer/__tests__/natural-graha-nature.test.ts</code></a></li></ul><p>Run the linked tests, then the complete offline contract:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/verify_project.py</span></span></code></pre></div><h2 id="public-surfaces" tabindex="-1">Public surfaces <a class="header-anchor" href="#public-surfaces" aria-label="Permalink to &quot;Public surfaces&quot;">​</a></h2><ul><li><code>python-library</code></li><li><code>website</code></li><li><code>generated-data</code></li></ul><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>No event scorer consumes this primitive at this snapshot, so it changes no ranking by itself.</li><li>Natural nature is not functional lordship, dignity, strength, combustion, aspect, degree conjunction or event suitability.</li><li>A complete nine-graha set is mandatory; malformed or incomplete data makes every nature unknown.</li><li>The predicates evaluate one chart state and do not prove every transition inside a Muhurtam window.</li></ul><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><ul><li><strong>owner:</strong> <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/telugu_panchangam/personal/election_assessors/graha_nature.py" target="_blank" rel="noreferrer"><code>telugu_panchangam/personal/election_assessors/graha_nature.py</code></a> — <code>classify_natural_graha_natures</code></li><li><strong>owner:</strong> <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/telugu_panchangam/personal/election_assessors/graha_nature.py" target="_blank" rel="noreferrer"><code>telugu_panchangam/personal/election_assessors/graha_nature.py</code></a> — <code>evaluate_existential_benefic_house_set</code></li><li><strong>owner:</strong> <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/telugu_panchangam/personal/election_assessors/graha_nature.py" target="_blank" rel="noreferrer"><code>telugu_panchangam/personal/election_assessors/graha_nature.py</code></a> — <code>evaluate_forbidden_malefic_house_set</code></li><li><strong>mirror:</strong> <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/src/scorer/election-assessors/graha-nature.ts" target="_blank" rel="noreferrer"><code>src/scorer/election-assessors/graha-nature.ts</code></a> — <code>classifyNaturalGrahaNatures</code></li><li><strong>mirror:</strong> <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/src/scorer/election-assessors/graha-nature.ts" target="_blank" rel="noreferrer"><code>src/scorer/election-assessors/graha-nature.ts</code></a> — <code>evaluateExistentialBeneficHouseSet</code></li><li><strong>mirror:</strong> <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/src/scorer/election-assessors/graha-nature.ts" target="_blank" rel="noreferrer"><code>src/scorer/election-assessors/graha-nature.ts</code></a> — <code>evaluateForbiddenMaleficHouseSet</code></li></ul><p>This route is generated from <a href="/docs/reference/computations.json"><code>computations.json</code></a>. Edit the registry and canonical reference prose in the same pull request as a behavior change.</p>',82)])])}const g=a(o,[["render",s]]);export{p as __pageData,g as default};
